import static org.mockito.Mockito.*;

public class JettyContextsend_ResponsesetStatusFikaTest {

    @Test
    public void testSendStatusCode() {
        Request mockRequest = mock(Request.class);
        Response mockResponse = mock(Response.class);
        Router mockRouter = mock(Router.class);

        when(mockRequest.getResponse()).thenReturn(mockResponse);
        when(mockRequest.getMethod()).thenReturn("GET");
        when(mockRequest.getRequestURI()).thenReturn("/test");

        JettyContext jettyContext = new JettyContext(mockRequest, mockRouter, 8192, 1000000L);

        StatusCode statusCode = StatusCode.OK;

        jettyContext.send(statusCode);

        verify(mockResponse, times(1)).setStatus(statusCode.value());
    }
}

