public Server start(Jooby application) {
    try {
        System.setProperty("org.eclipse.jetty.util.UrlEncoded.charset", "utf-8");
        /**
         * Set max request size attribute:
         */
        System.setProperty("org.eclipse.jetty.server.Request.maxFormContentSize", Long.toString(options.getMaxRequestSize()));
        applications.add(application);
