package io.jooby.jetty;

import io.jooby.Jooby;
import io.jooby.ServerOptions;
import io.jooby.SslOptions;
import org.junit.jupiter.api.Test;

import javax.net.ssl.SSLContext;
import java.security.NoSuchAlgorithmException;

public class Jettystart_WebSocketPolicysetIdleTimeoutFikaTest {

    @Test
    public void testStart() throws Exception {
        Jetty jetty = new Jetty();

        ServerOptions options = new ServerOptions();
        options.setPort(0);
        options.setSecurePort(0);

        // Configure WebSocket idle timeout via config
        Jooby application = new Jooby();
        application.getConfig().put("websocket.idleTimeout", "1000ms");

        // Set SSL disabled to avoid SSL setup
        SslOptions sslOptions = new SslOptions();
        sslOptions.setType(SslOptions.ClientAuth.NONE);
        options.setSsl(sslOptions);

        // Set HTTP2 disabled to simplify setup
        options.setHttp2(false);

        // Set HTTPS only to false
        options.setHttpsOnly(false);

        // Use reflection to set options field since there's no setter
        try {
            java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
            optionsField.setAccessible(true);
            optionsField.set(jetty, options);
        } catch (NoSuchFieldException | IllegalAccessException e) {
            throw new RuntimeException(e);
        }

        jetty.start(application);
    }
}

