import com.typesafe.config.Config;
import com.typesafe.config.ConfigFactory;
import io.jooby.Environment;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.concurrent.TimeUnit;

public class Jettystart_WebSocketPolicysetMaxTextMessageSizeFikaTest {

    @Test
    public void testStartInvokesWebSocketPolicySetMaxTextMessageSize() throws Exception {
        // Create a mock Jooby application
        Jooby application = Mockito.mock(Jooby.class);

        // Create a mock Environment
        Environment environment = Mockito.mock(Environment.class);

        // Create a mock Config with websocket.maxSize property
        Config config = ConfigFactory.parseString(
            "websocket.maxSize = 65536\n" +
            "websocket.idleTimeout = \"5 minutes\""
        );

        // Setup mock behavior
        Mockito.when(application.getConfig()).thenReturn(config);
        Mockito.when(application.getEnvironment()).thenReturn(environment);
        Mockito.when(environment.getClassLoader()).thenReturn(Thread.currentThread().getContextClassLoader());

        // Create Jetty instance
        Jetty jetty = new Jetty();

        // Configure server options to avoid SSL and enable HTTP
        ServerOptions options = new ServerOptions()
            .setPort(0)  // Use port 0 for automatic port assignment
            .setHost("localhost")
            .setHttpsOnly(false)
            .setSSLEnabled(false);

        // Use reflection to set the options field since there's no setter
        try {
            java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
            optionsField.setAccessible(true);
            optionsField.set(jetty, options);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Start the server - this should trigger the WebSocketPolicy.setMaxTextMessageSize call
        jetty.start(application);

        // Clean up
        jetty.stop();
    }
}

