    public void testStart() throws Exception {
        Jetty jetty = new Jetty();

        ServerOptions options = new ServerOptions();
        options.setPort(8080);
        options.setHost("localhost");
        options.setBufferSize(8192);
        options.setMaxRequestSize(10485760L);
        options.setWorkerThreads(200);
        options.setDefaultHeaders(true);

        // Set SSL to false to avoid https path
        Method setSSLEnabledMethod = ServerOptions.class.getDeclaredMethod("setSSLEnabled", boolean.class);
        setSSLEnabledMethod.setAccessible(true);
        setSSLEnabledMethod.invoke(options, false);

        // Set httpsOnly to false
        Method setHttpsOnlyMethod = ServerOptions.class.getDeclaredMethod("setHttpsOnly", boolean.class);
        setHttpsOnlyMethod.setAccessible(true);
        setHttpsOnlyMethod.invoke(options, false);

        // Set http2 to false
        Method setHttp2Method = ServerOptions.class.getDeclaredMethod("setHttp2", Boolean.class);
        setHttp2Method.setAccessible(true);
        setHttp2Method.invoke(options, false);

        // Set compression level to null
        Method setCompressionLevelMethod = ServerOptions.class.getDeclaredMethod("setCompressionLevel", Integer.class);
        setCompressionLevelMethod.setAccessible(true);
        setCompressionLevelMethod.invoke(options, (Integer) null);

        // Use reflection to set the options field
        java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        optionsField.set(jetty, options);

        Jooby mockJooby = Mockito.mock(Jooby.class);
        io.jooby.Environment mockEnvironment = Mockito.mock(io.jooby.Environment.class);
        Mockito.when(mockJooby.getEnvironment()).thenReturn(mockEnvironment);
        Mockito.when(mockEnvironment.getClassLoader()).thenReturn(Thread.currentThread().getContextClassLoader());

        com.typesafe.config.Config mockConfig = Mockito.mock(com.typesafe.config.Config.class);
        Mockito.when(mockJooby.getConfig()).thenReturn(mockConfig);

        jetty.start(mockJooby);
    }
}

