package io.jooby.jetty;

import com.typesafe.config.Config;
import io.jooby.Environment;
import io.jooby.Jooby;
import io.jooby.ServerOptions;
import io.jooby.SslOptions;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import javax.net.ssl.SSLContext;
import java.util.concurrent.TimeUnit;

public class Jettystart_ConfiggetDurationFikaTest {

    @Test
    public void testStart() throws Exception {
        // Create Jetty instance
        Jetty jetty = new Jetty();

        // Create mock Jooby application
        Jooby application = Mockito.mock(Jooby.class);
        Environment environment = Mockito.mock(Environment.class);
        Config config = Mockito.mock(Config.class);

        // Configure the mock config to have the required path
        Mockito.when(config.hasPath("websocket.maxSize")).thenReturn(false);
        Mockito.when(config.hasPath("websocket.idleTimeout")).thenReturn(true);
        Mockito.when(config.getDuration(Mockito.eq("websocket.idleTimeout"), Mockito.eq(TimeUnit.MILLISECONDS)))
               .thenReturn(TimeUnit.MINUTES.toMillis(5));

        // Configure environment and application
        Mockito.when(application.getEnvironment()).thenReturn(environment);
        Mockito.when(application.getConfig()).thenReturn(config);
        Mockito.when(environment.getClassLoader()).thenReturn(ClassLoader.getSystemClassLoader());

        // Configure SSL context for options
        SSLContext sslContext = SSLContext.getDefault();
        SslOptions sslOptions = new SslOptions();

        // Get and configure ServerOptions from Jetty
        ServerOptions options = new ServerOptions()
            .setServer("jetty")
            .setWorkerThreads(200)
            .setBufferSize(8192)
            .setMaxRequestSize(1048576L)
            .setDefaultHeaders(true)
            .setPort(8080)
            .setHost("0.0.0.0")
            .setHttpsOnly(false)
            .setSSLEnabled(false)
            .setSsl(sslOptions);

        // Use reflection to set the options field since there's no setter
        try {
            java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
            optionsField.setAccessible(true);
            optionsField.set(jetty, options);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Start the server
        jetty.start(application);
    }
}

