import io.jooby.ServerOptions;
import io.jooby.SslOptions;
import com.typesafe.config.Config;
import com.typesafe.config.ConfigFactory;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import javax.net.ssl.SSLContext;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;

public class Jettystart_WebSocketPolicysetMaxTextMessageBufferSizeFikaTest {

    @Test
    public void testStart() throws Exception {
        // Create Jetty instance
        Jetty jetty = new Jetty();

        // Create mock Jooby application
        Jooby application = Mockito.mock(Jooby.class);

        // Create mock Environment
        io.jooby.Environment environment = Mockito.mock(io.jooby.Environment.class);
        Mockito.when(application.getEnvironment()).thenReturn(environment);
        Mockito.when(environment.getClassLoader()).thenReturn(Thread.currentThread().getContextClassLoader());

        // Create config with websocket.maxSize property
        HashMap<String, Object> configMap = new HashMap<>();
        configMap.put("websocket.maxSize", "1048576"); // 1MB
        configMap.put("websocket.idleTimeout", "300000"); // 5 minutes in milliseconds
        Config config = ConfigFactory.parseMap(configMap);
        Mockito.when(application.getConfig()).thenReturn(config);

        // Create mock Router
        io.jooby.Router router = Mockito.mock(io.jooby.Router.class);
        Mockito.when(application.getRouter()).thenReturn(router);

        // Configure ServerOptions
        ServerOptions options = new ServerOptions()
            .setPort(0) // Use port 0 for automatic port allocation
            .setHost("localhost")
            .setBufferSize(8192)
            .setMaxRequestSize(10485760L) // 10MB
            .setWorkerThreads(200)
            .setDefaultHeaders(false);

        // Use reflection to set the options field since there's no setter
        try {
            java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
            optionsField.setAccessible(true);
            optionsField.set(jetty, options);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Start the server
        jetty.start(application);
    }
}

