public class Jettystart_ServeraddConnectorFikaTest {

    @Test
    public void testStart() throws Exception {
        Jetty jetty = new Jetty();

        ServerOptions options = new ServerOptions();
        options.setPort(8080);
        options.setHost("localhost");
        options.setBufferSize(8192);
        options.setWorkerThreads(200);
        options.setMaxRequestSize(1000000L);
        options.setDefaultHeaders(true);
        options.setHttpsOnly(false);

        // Set SSL disabled to avoid SSL connector creation
        SslOptions sslOptions = new SslOptions();
        sslOptions.setPort(8443);

        // Use reflection to set private fields since there are no setters
        setField(jetty, "options", options);

        Jooby jooby = new Jooby();

        // Start the server
        jetty.start(jooby);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }
}

