public class Jettystart_HttpConfigurationsetOutputAggregationSizeFikaTest {

    @Test
    public void testStartCallsSetOutputAggregationSize() throws Exception {
        Jetty jetty = new Jetty();

        ServerOptions options = new ServerOptions();
        options.setPort(0);
        options.setSecurePort(0);
        options.setBufferSize(8192);

        SslOptions sslOptions = new SslOptions();
        sslOptions.setPort(0);
        sslOptions.setSecurePort(0);
        options.setSsl(sslOptions);

        try {
            SSLContext sslContext = SSLContext.getDefault();
            sslOptions.setSSLContext(sslContext);
        } catch (NoSuchAlgorithmException e) {
            // Use null SSLContext if default is not available
            sslOptions.setSSLContext(null);
        }

        // Use reflection to set the options field since there's no setter
        java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        optionsField.set(jetty, options);

        Jooby application = new Jooby();

        jetty.start(application);
    }
}

