public class Jettystart_HttpConfigurationaddCustomizerFikaTest {

    @Test
    public void testStart() throws Exception {
        Jetty jetty = new Jetty();

        ServerOptions options = new ServerOptions();
        SslOptions sslOptions = new SslOptions();

        // Configure SSL to ensure the code path with addCustomizer is executed
        sslOptions.setSSLContext(SSLContext.getDefault());
