    @Test
    public void testStartMethodInvokesWebSocketPolicyConstructor() throws Exception {
        // Create instance of class under test
        Jetty jetty = new Jetty();

        // Create mock Jooby application
        Jooby mockApplication = Mockito.mock(Jooby.class);
        io.jooby.Environment mockEnvironment = Mockito.mock(io.jooby.Environment.class);
        com.typesafe.config.Config mockConfig = Mockito.mock(com.typesafe.config.Config.class);

        // Configure mock behavior
        when(mockApplication.getEnvironment()).thenReturn(mockEnvironment);
        when(mockEnvironment.getClassLoader()).thenReturn(ClassLoader.getSystemClassLoader());
        when(mockApplication.getConfig()).thenReturn(mockConfig);

        // Configure config to have websocket.maxSize and websocket.idleTimeout
        when(mockConfig.hasPath("websocket.maxSize")).thenReturn(true);
        when(mockConfig.getBytes("websocket.maxSize")).thenReturn(1024L);
        when(mockConfig.hasPath("websocket.idleTimeout")).thenReturn(true);
        when(mockConfig.getDuration("websocket.idleTimeout", TimeUnit.MILLISECONDS))
            .thenReturn(300000L); // 5 minutes in milliseconds

        // Create and configure ServerOptions
        ServerOptions options = new ServerOptions();
        options.setPort(8080);
        options.setHost("localhost");
        options.setWorkerThreads(200);
        options.setBufferSize(8192);
        options.setMaxRequestSize(1048576L);
        options.setDefaultHeaders(true);
        options.setHttp2(null);
        options.setHttpsOnly(false);
        options.setSSLEnabled(false);

        // Set options on jetty instance using reflection since there's no setter
        java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        optionsField.set(jetty, options);

        // Call the entry point method
        jetty.start(mockApplication);
    }
}

