        ContextHandler context = new ContextHandler();
        AbstractHandler handler = new JettyHandler(applications.get(0), options.getBufferSize(), options.getMaxRequestSize(), options.getDefaultHeaders());
        if (options.getCompressionLevel() != null) {
            GzipHandler gzipHandler = new GzipHandler();
            gzipHandler.setCompressionLevel(options.getCompressionLevel());
            gzipHandler.setHandler(handler);
            context.setHandler(gzipHandler);
        } else {
            context.setHandler(handler);
        }
