package io.jooby.jetty;

import com.typesafe.config.Config;
import io.jooby.Environment;
import io.jooby.Jooby;
import io.jooby.ServerOptions;
import io.jooby.SslOptions;
import org.eclipse.jetty.util.thread.QueuedThreadPool;
import org.junit.jupiter.api.Test;

import javax.net.ssl.SSLContext;
import java.util.concurrent.TimeUnit;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class Jettystart_ConfiggetBytesFikaTest {

    @Test
    public void testStart() throws Exception {
        // Create Jetty instance
        Jetty jetty = new Jetty();

        // Create mock Jooby
        Jooby mockJooby = mock(Jooby.class);

        // Create mock Environment
        Environment mockEnvironment = mock(Environment.class);
        when(mockJooby.getEnvironment()).thenReturn(mockEnvironment);
        when(mockEnvironment.getClassLoader()).thenReturn(Thread.currentThread().getContextClassLoader());

        // Create mock Config that will be called for getBytes
        Config mockConfig = mock(Config.class);
        when(mockJooby.getConfig()).thenReturn(mockConfig);

        // Configure mock Config to return a value for getBytes
        when(mockConfig.hasPath("websocket.maxSize")).thenReturn(true);
        when(mockConfig.getBytes("websocket.maxSize")).thenReturn(1024L);
        when(mockConfig.hasPath("websocket.idleTimeout")).thenReturn(false);

        // Configure ServerOptions
        ServerOptions options = new ServerOptions();
        options.setPort(0); // Use port 0 to avoid binding conflicts
        options.setSecurePort(8443);
        options.setHost("localhost");
        options.setWorkerThreads(10); // Reduced for test
        options.setBufferSize(8192);
        options.setMaxRequestSize(1048576L);
        options.setDefaultHeaders(true);

        // Set SSL options to avoid SSL configuration
        SslOptions sslOptions = new SslOptions();
        sslOptions.setProtocol("TLSv1.2");
        options.setSsl(sslOptions);

        // Use reflection to set the options field since there's no setter
        try {
            java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
            optionsField.setAccessible(true);
            optionsField.set(jetty, options);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Start the server
        jetty.start(mockJooby);
    }
}

