public class Jettystart_ConfiggetBytesFikaTest {

    @Test
    public void start() throws Exception {
        // Create Jetty instance
        Jetty jetty = new Jetty();

        // Create mock Jooby with mock Environment and Config
        Jooby application = Mockito.mock(Jooby.class);
        Environment environment = Mockito.mock(Environment.class);
        Config config = Mockito.mock(Config.class);

        // Setup mock chain: application -> environment -> config
        Mockito.when(application.getEnvironment()).thenReturn(environment);
        Mockito.when(application.getConfig()).thenReturn(config);

        // Setup config to have the path "websocket.maxSize" so getBytes is called
        Mockito.when(config.hasPath("websocket.maxSize")).thenReturn(true);
        Mockito.when(config.getBytes("websocket.maxSize")).thenReturn(1024L);

        // Also setup "websocket.idleTimeout" to avoid NPE
        Mockito.when(config.hasPath("websocket.idleTimeout")).thenReturn(false);

        // Setup SSL context to avoid NPE when SSL is checked
        Mockito.when(environment.getClassLoader()).thenReturn(ClassLoader.getSystemClassLoader());

        // Modify options to avoid SSL path (simpler execution)
        ServerOptions options = new ServerOptions();
        options.setPort(0); // Use port 0 to avoid bind conflicts
        options.setSecurePort(8443);
        options.setHttpsOnly(false);
        options.setSSLEnabled(false);

        // Use reflection to set the private options field
        java.lang.reflect.Field optionsField = Jetty.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        optionsField.set(jetty, options);

        // Start the server (will call config.getBytes("websocket.maxSize"))
        jetty.start(application);
    }
}

