        if (x != null) {
            if (Server.connectionLost(x)) {
                log.debug("exception found while sending response {} {}", getMethod(), getRequestPath(), x);
            } else {
                log.error("exception found while sending response {} {}", getMethod(), getRequestPath(), x);
            }
        }
    } finally {
        responseDone();
    }
}

