    void testCloseTriggersResponseDoneAndGetAsyncContext() throws IOException {
        OutputStream mockOutputStream = mock(OutputStream.class);

        Request mockRequest = mock(Request.class);
        AsyncContext mockAsyncContext = mock(AsyncContext.class);
        when(mockRequest.isAsyncStarted()).thenReturn(true);
        when(mockRequest.getAsyncContext()).thenReturn(mockAsyncContext);

        JettyContext realJettyContext = new JettyContext();
        realJettyContext.request = mockRequest;

        JettyOutputStream jettyOutputStream = new JettyOutputStream(mockOutputStream, realJettyContext);

        jettyOutputStream.close();
    }

    private static class JettyContext {
        Request request;
        CompletionListeners listeners;

        void responseDone() {
            try {
                ifSaveSession();
                clearFiles();
            } finally {
                if (request.isAsyncStarted()) {
                    request.getAsyncContext().complete();
                }
                if (listeners != null) {
                    listeners.run(this);
                }
            }
        }

        private void ifSaveSession() {}

        private void clearFiles() {}
    }

    private static class JettyOutputStream {
        private JettyContext jetty;
        private OutputStream out;

        public JettyOutputStream(OutputStream out, JettyContext jetty) {
            this.out = out;
            this.jetty = jetty;
        }

        public void close() throws IOException {
            try {
                out.close();
            } finally {
                jetty.responseDone();
            }
        }
    }

    private interface CompletionListeners {
        void run(JettyContext context);
    }
}

